import java.time.LocalDateTime;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.time.format.ResolverStyle;

public class ReportWindow {
    private static final DateTimeFormatter FORMAT =
        DateTimeFormatter.ofPattern("uuuu-MM-dd HH:mm").withResolverStyle(ResolverStyle.STRICT);
    private static final ZoneId STORE_ZONE = ZoneId.of("Europe/Paris");

    /** Parses a local report boundary. A local time that does not exist must be rejected. */
    public static ZonedDateTime parseBoundary(String text) {
        LocalDateTime local = LocalDateTime.parse(text, FORMAT);
        return local.atZone(STORE_ZONE);
    }
}
